{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(df):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "input",
      "expression": "hasattr(df, 'select_dtypes') and hasattr(df, 'describe') and hasattr(df, 'copy')",
      "description": "df is a pandas-like DataFrame supporting numeric-column selection, descriptive statistics, and copying."
    },
    {
      "id": "P2",
      "target": "df",
      "expression": "len(df.select_dtypes(include=[np.number]).columns) > 0",
      "description": "df contains at least one numeric column to describe and plot."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "len(result[1]) == len(df.select_dtypes(include=[np.number]).columns) and all(hasattr(ax, 'patches') for ax in result[1])",
      "description": "The second returned value contains one matplotlib Axes-like distribution plot for each numeric column."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "The first returned value is a DataFrame-like descriptive statistics table with the standard pandas describe statistic rows."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "list(result[0].columns) == list(df.select_dtypes(include=[np.number]).columns)",
      "description": "The statistics table contains exactly the numeric columns from the input DataFrame, in their original order."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "np.allclose(result[0].loc['mean'].to_numpy(dtype=float), df.select_dtypes(include=[np.number]).apply(lambda s: s.fillna(s.mean())).mean().to_numpy(dtype=float), equal_nan=True)",
      "description": "NaN values in each numeric column are replaced by that column's mean before computing the reported means."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "all(len(ax.patches) == 10 for ax in result[1])",
      "description": "Each distribution plot uses 10 histogram bins."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(documents):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "documents",
      "expression": "isinstance(documents, list) and all(isinstance(doc, str) for doc in documents)",
      "description": "documents is a list whose elements are text documents represented as strings."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result.shape == TfidfVectorizer(tokenizer=word_tokenize).fit_transform(documents).shape",
      "description": "The returned TF-IDF matrix has the same number of rows and vocabulary columns as sklearn's TfidfVectorizer fitted and transformed on the input documents with word_tokenize."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "isinstance(result, pd.DataFrame) and result.shape[0] == len(documents)",
      "description": "The function returns a pandas DataFrame with one row for each input document."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "all(isinstance(col, str) for col in result.columns) and len(result.columns) > 0",
      "description": "The DataFrame columns are non-empty string token features from the fitted TF-IDF vocabulary."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result.values.dtype.kind == 'f' and (result.values >= 0).all()",
      "description": "Each cell is a non-negative floating-point TF-IDF score for the corresponding token in the corresponding document."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "set(result.columns) == set(TfidfVectorizer(tokenizer=word_tokenize).fit(documents).get_feature_names_out())",
      "description": "The DataFrame columns match the vocabulary learned by sklearn.feature_extraction.text.TfidfVectorizer using nltk.tokenize.word_tokenize on the input documents."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
