    {
      "id": "Q2",
      "target": "return",
      "expression": "len(result) == min(N, len(df))",
      "description": "The returned list contains at most N indices and no more indices than there are rows in the DataFrame."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(news_articles):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "news_articles",
      "expression": "isinstance(news_articles, list)",
      "description": "The input is a list of article dictionaries."
    },
    {
      "id": "P2",
      "target": "article",
      "expression": "all(isinstance(article, dict) for article in news_articles)",
      "description": "Every element of the input list is a dictionary representing one article."
    },
    {
      "id": "P3",
      "target": "input",
      "expression": "all(set(article.keys()) == {'title', 'title_url', 'id', 'category'} for article in news_articles)",
      "description": "Each article dictionary has exactly the required keys: 'title', 'title_url', 'id', and 'category'; otherwise the function raises ValueError."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "[article for articles in result.values() for article in articles] == sorted(news_articles, key=itemgetter('category', 'title'))",
      "description": "Across all groups in insertion order, the articles match the input articles sorted first by 'category' and then by 'title'."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "set(result.keys()) == {article['category'] for article in news_articles}",
      "description": "The returned mapping has exactly one key for each category present in the input articles."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "all(result[category] == sorted([article for article in news_articles if article['category'] == category], key=itemgetter('title')) for category in result)",
      "description": "For each category, the value is the list of articles from that category sorted by their 'title' field."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(LETTERS):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "LETTERS",
