    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "all(isinstance(mean, (int, float, np.number)) and 0 <= mean <= 100 for mean in result.values())",
      "description": "Every returned value is a numeric mean within the inclusive range 0 to 100 because it is computed from generated integers in that range."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "(not (len(LETTERS) == 0)) or (result == {})",
      "description": "If the input list is empty, no random lists are generated and the returned dictionary is empty."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(df):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "input",
      "expression": "hasattr(df, 'columns') and {'feature', 'value'}.issubset(df.columns)",
      "description": "df provides columns named 'feature' and 'value'."
    },
    {
      "id": "P2",
      "target": "df",
      "expression": "len(df) >= 1",
      "description": "There is at least one observation to fit the regression model."
    },
    {
      "id": "P3",
      "target": "input",
      "expression": "np.isfinite(df[['feature', 'value']].to_numpy(dtype=float)).all()",
      "description": "The feature and value columns contain numeric, finite, non-missing values acceptable to scikit-learn LinearRegression."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "The coefficients entry equals the fitted regression model's coefficient array serialized with .tolist(), giving one coefficient for the single feature and target."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "Fits a scikit-learn LinearRegression model using df[['feature']] as the predictor matrix and df[['value']] as the target, then returns the learned coefficients and intercept converted to Python lists."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "set(result.keys()) == {'coefficients', 'intercept'}",
      "description": "The returned dictionary contains exactly the model coefficient entry and the model intercept entry."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "The intercept entry equals the fitted regression model's intercept array serialized with .tolist()."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(num_labels=5, data_range=(0, 1)):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "data_range",
      "expression": "isinstance(data_range, tuple) and len(data_range) == 2 and all(isinstance(x, (int, float, np.integer, np.floating)) for x in data_range) and data_range[0] < data_range[1]",
      "description": "data_range is a two-element numeric tuple with a lower bound strictly less than the upper bound."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "all(np.isfinite([p.get_height() for ax in result.axes for p in ax.patches]))",
      "description": "All plotted bar segment heights are finite numeric values generated for the stacked bar chart."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "len(result.axes) >= 1 and len(result.axes[0].patches) > 0",
      "description": "The returned Figure contains an Axes with bar patches representing the generated data."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "len(result.axes[0].get_xticklabels()) == num_labels or len(result.axes[0].containers) >= 1",
      "description": "The chart displays generated data for the requested number of labels or contains bar containers produced by plotting those category data."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(a, b):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "a",
      "expression": "isinstance(a, list) and isinstance(b, list)",
      "description": "Both inputs are provided as lists."
    },
    {
      "id": "P2",
      "target": "a",
      "expression": "len(a) == len(b)",
      "description": "The two lists have the same length so their Euclidean distance and paired DataFrame columns can be computed."
    },
    {
      "id": "P3",
      "target": "x",
      "expression": "all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in a + b)",
      "description": "All elements of both lists are numeric values suitable for distance calculation and plotting."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "hasattr(result[2], 'plot') and result[2].get_title() == f'Euclidean Distance: {result[0]:.2f}'",
      "description": "The third returned value is a Matplotlib Axes object for a line plot titled with the computed Euclidean distance."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "isinstance(result[0], float) and result[0] == distance.euclidean(a, b)",
      "description": "The first returned value is the Euclidean distance between the two input lists."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], a)",
      "description": "The second returned value is a DataFrame whose columns are named 'A' and 'B' and contain the original input lists."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "a == old_a and b == old_b",
      "description": "The input lists are not mutated by the function."
    }
  ]
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(hex_string):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "hex_string",
      "expression": "isinstance(hex_string, str)",
      "description": "The input is a string containing hexadecimal characters."
    },
    {
      "id": "P2",
      "target": "input",
      "expression": "can_decode_hex_to_utf8(hex_string)",
      "description": "The hexadecimal string can be decoded to bytes and those bytes can be decoded as UTF-8 text."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result == {'hex': binascii.hexlify(binascii.unhexlify(hex_string)).decode('utf-8'), 'base64': base64.b64encode(binascii.unhexlify(hex_string)).decode('utf-8'), 'utf-8': binascii.unhexlify(hex_string).decode('utf-8'), 'utf-16': binascii.unhexlify(hex_string).decode('utf-8'), 'utf-32': binascii.unhexlify(hex_string).decode('utf-8'), 'ASCII': (binascii.unhexlify(hex_string).decode('utf-8') if can_encode_ascii(binascii.unhexlify(hex_string).decode('utf-8')) else 'Not representable in ASCII'), 'URL': urllib.parse.quote(binascii.unhexlify(hex_string).decode('utf-8')), 'ROT13': codecs.encode(binascii.unhexlify(hex_string).decode('utf-8'), 'rot_13')}",
      "description": "The returned dictionary maps each required encoding label to the corresponding representation derived from the bytes decoded from the hexadecimal input."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "set(result.keys()) == {'hex', 'base64', 'utf-8', 'utf-16', 'utf-32', 'ASCII', 'URL', 'ROT13'}",
      "description": "The result contains exactly the documented encoding keys."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "result['utf-8'] == binascii.unhexlify(hex_string).decode('utf-8') and result['utf-16'] == result['utf-8'] and result['utf-32'] == result['utf-8']",
      "description": "The UTF-8 decoded text is used directly for the utf-8, utf-16, and utf-32 entries as strings."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "result['ASCII'] == result['utf-8'] if can_encode_ascii(result['utf-8']) else result['ASCII'] == 'Not representable in ASCII'",
      "description": "The ASCII entry contains the decoded text when it is ASCII-representable, otherwise it contains the documented fallback message."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "target": "state",
      "expression": "input_not_modified(hex_string)",
      "description": "The input string is not modified by the function."
    }
  ]
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(text, n=2):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "text",
      "expression": "isinstance(text, str)",
      "description": "The input text must be a string."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "all(isinstance(k, tuple) and len(k) == n and all(isinstance(token, str) for token in k) and isinstance(v, int) and v >= 1 for k, v in result.items())",
      "description": "Each result key is an n-token tuple and each value is a positive integer count."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result == Counter(tuple(filtered_tokens[i:i+n]) for i in range(len(filtered_tokens) - n + 1))",
      "description": "The result counts contiguous n-grams formed after tokenizing text, removing English stopwords, and removing duplicate tokens according to the implementation's filtered_tokens sequence."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(df):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "input",
      "expression": "hasattr(df, 'columns')",
      "description": "df is DataFrame-like and exposes a columns collection so the function can check whether 'Title' and 'Content' are present."
    },
    {
      "id": "P2",
      "target": "input",
      "expression": "('Title' not in df.columns and 'Content' not in df.columns) or hasattr(df, '__getitem__')",
