    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "axes_displays_category_value_bar_chart(result[1], df)",
      "description": "For matching articles, the x-axis tick labels correspond to the TF-IDF feature names from the selected contents."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result.__class__.__name__ == 'Axes'",
      "description": "The function returns a matplotlib Axes object."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "result.get_ylabel() == 'TF-IDF Score'",
      "description": "The returned Axes has its y-axis label set to 'TF-IDF Score'."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "(not ((('Title' not in df.columns) or ('Content' not in df.columns)))) or (len(result.patches) == 0)",
      "description": "If df lacks either required column, the returned plot contains no TF-IDF bars."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "(not (has_required_columns(df, ['Title', 'Content']) and no_titles_match_words(df['Title'], ['how', 'what']))) or (len(result.patches) == 0)",
      "description": "If no article title contains the word 'how' or 'what', the returned plot contains no TF-IDF bars."
    },
    {
      "id": "Q6",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "For matching articles, the number of bars equals the number of feature names produced by TfidfVectorizer from the selected Content values."
    },
    {
      "id": "Q7",
      "target": "return",
      "expression": "(not (has_required_columns(df, ['Title', 'Content']) and any_titles_match_words(df['Title'], ['how', 'what']))) or (all_xtick_labels_vertical(result))",
      "description": "Feature-name tick labels on the x-axis are displayed vertically."
    },
    {
      "id": "Q8",
      "target": "return",
      "expression": "dataframe_matches_category_value_pairs(result[0], df)",
      "description": "For matching articles, each bar height represents the aggregated TF-IDF score for the corresponding feature computed from only those selected Content values."
    }
  ],
  "invariants": []
}

