{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(data, columns):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "data",
      "expression": "isinstance(data, dict)",
      "description": "Input data is provided as a dictionary mapping column names to column values."
    },
    {
      "id": "P2",
      "target": "columns",
      "expression": "isinstance(columns, list) and all(isinstance(c, str) for c in columns)",
      "description": "The columns argument is a list of column names to normalize."
    },
    {
      "id": "P3",
      "target": "columns",
      "expression": "all(c in data for c in columns)",
      "description": "Every requested column to normalize exists in the input data."
    },
    {
      "id": "P4",
      "target": "input",
      "expression": "columns_are_minmax_scalable(pd.DataFrame(data), columns)",
      "description": "The specified columns contain values suitable for sklearn.preprocessing.MinMaxScaler transformation."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "dataframe_equal_except_columns(result, pd.DataFrame(data), columns)",
      "description": "The returned DataFrame has the same data as the input converted to a DataFrame except that the specified columns are replaced by their normalized values."
