{
  "interface": {
    "function_name": "task_func",
    "signature": "def task_func(dataframe, text_column):"
  },
  "preconditions": [
    {
      "id": "P1",
      "target": "dataframe",
      "expression": "isinstance(dataframe, pd.DataFrame)",
      "description": "The input dataframe must be a pandas DataFrame."
    },
    {
      "id": "P2",
      "target": "text_column",
      "expression": "isinstance(text_column, str) and text_column in dataframe.columns",
      "description": "text_column must be the name of an existing column in the DataFrame."
    },
    {
      "id": "P3",
      "target": "x",
      "expression": "dataframe[text_column].map(lambda x: isinstance(x, str)).all()",
      "description": "All values in the specified text column must be strings so they can be preprocessed and vectorized."
    },
    {
      "id": "P4",
      "target": "input",
      "expression": "dataframe[text_column].map(lambda s: len([w for w in re.sub(r'[^a-zA-Z\\s]', ' ', s.lower()).split() if w not in STOPWORDS]) > 0).any()",
      "description": "At least one row must contain a non-stopword alphabetic token after lowercasing and removing numbers and punctuation, so CountVectorizer can build a vocabulary."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result.shape[0] == len(dataframe)",
      "description": "The returned DataFrame has one row for each input row."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "all(isinstance(col, str) and col == col.lower() and re.fullmatch(r'[a-zA-Z]+', col) and col not in STOPWORDS for col in result.columns)",
      "description": "Each output column is a lowercase alphabetic token produced after removing punctuation, numbers, and stopwords."
    },
    {
      "id": "Q3",
      "target": "return",
      "expression": "result.applymap(lambda x: isinstance(x, (int, float)) and x >= 0 and float(x).is_integer()).to_numpy().all()",
      "description": "All output cells are non-negative integer token counts."
    },
    {
      "id": "Q4",
      "target": "return",
      "expression": "set(result.columns) == set(CountVectorizer().fit(dataframe[text_column].map(lambda s: ' '.join([w for w in re.sub(r'[^a-zA-Z\\s]', ' ', s.lower()).split() if w not in STOPWORDS]))).get_feature_names_out())",
      "description": "The output columns are exactly the vocabulary learned from the preprocessed text."
    },
    {
      "id": "Q5",
      "target": "return",
      "expression": "result.equals(pd.DataFrame(CountVectorizer().fit_transform(dataframe[text_column].map(lambda s: ' '.join([w for w in re.sub(r'[^a-zA-Z\\s]', ' ', s.lower()).split() if w not in STOPWORDS]))).toarray(), columns=CountVectorizer().fit(dataframe[text_column].map(lambda s: ' '.join([w for w in re.sub(r'[^a-zA-Z\\s]', ' ', s.lower()).split() if w not in STOPWORDS]))).get_feature_names_out()))",
      "description": "The returned DataFrame contains the same bag-of-words counts as applying CountVectorizer to the specified column after lowercasing, removing numbers and punctuation, and filtering STOPWORDS."
    }
  ],
  "invariants": []
}

