    {
      "id": "P1",
      "target": "l1",
      "expression": "isinstance(l1, list) and isinstance(l2, list)",
      "description": "Both inputs are lists."
    },
    {
      "id": "P2",
      "target": "x",
      "expression": "all(isinstance(x, (int, float, np.number)) and not isinstance(x, (bool, np.bool_)) for x in l1 + l2)",
      "description": "All elements in both lists are non-boolean numeric values."
    },
    {
      "id": "P3",
      "target": "THRESHOLD",
      "expression": "isinstance(THRESHOLD, (int, float, np.number)) and not isinstance(THRESHOLD, (bool, np.bool_))",
      "description": "The threshold is a non-boolean numeric value."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "target": "return",
      "expression": "result == first_min_by_abs_distance(interleave_existing_elements(l1, l2), THRESHOLD)",
      "description": "The returned value is the first element in alternating existing-element order whose absolute difference from the threshold is minimal."
    },
    {
      "id": "Q2",
      "target": "return",
      "expression": "result in l1 + l2",
      "description": "The returned value is one of the original input elements."
